import java.util.*; public class WarehouseInventoryBalancer{static void analyzeInventory(int[] a,int[] b){int x=0,y=0,m=Integer.MIN_VALUE,sec=0,idx=0;for(int i=0;i<a.length;i++){x+=a[i];if(a[i]>m){m=a[i];sec=1;idx=i+1;}}for(int i=0;i<b.length;i++){y+=b[i];if(b[i]>m){m=b[i];sec=2;idx=i+1;}}System.out.println("Section A Total: "+x+" | Section B Total: "+y+" | Status: "+(x==y?"Balanced":"Not Balanced")+" | Highest Quantity: "+m+" (Section "+(sec==1?"A":"B")+", Item "+idx+")");}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();int[] a=new int[n],b=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int i=0;i<n;i++)b[i]=s.nextInt();analyzeInventory(a,b);}}